    """Tuned Best Fit (lo=8, hi=32, penalty=64): the tightest bin wins, but leaving a gap
    strictly between 8 and 32 units costs 64. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 64 * ((r > 8) & (r < 32))

