    """Tuned Best Fit (lo=8, hi=10, penalty=98): the tightest bin wins, but leaving a gap
    strictly between 8 and 10 units costs 98. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 98 * ((r > 8) & (r < 10))

